using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Academy.Api.Auth;
using Academy.Api.Operations;
using Academy.Api.Slice4;
using Academy.Infrastructure.Attendance;
using Academy.Infrastructure.Persistence;
using Academy.Infrastructure.Tenancy;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;

namespace Academy.IntegrationTests;
public sealed partial class V2PlanPublicationTests
{
    private static string CorrectionPath(Guid session)=>$"/api/v1/attendance/sessions/{session}/corrections";
    private static AttendanceCorrectionWrite CorrectionBody(Guid subject,uint version=0,AttendanceStatus after=AttendanceStatus.Absent,AttendanceCorrectionKind kind=AttendanceCorrectionKind.Players)=>new(kind,[new(subject,after,version)],"تصحيح ورقي راجعته الإدارة — بيانات اصطناعية");
    private async Task<Guid> RequestCorrection(HttpClient c,Guid session,AttendanceCorrectionWrite body,string? key=null)
    {
        var r=await CompensationCommand(c,CorrectionPath(session),body,key);Assert.True(r.IsSuccessStatusCode,await r.Content.ReadAsStringAsync());return(await r.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();
    }
    private static async Task<uint> CorrectionVersion(HttpClient c,Guid id)=>(await c.GetFromJsonAsync<JsonElement>($"/api/v1/attendance/corrections/{id}")).GetProperty("version").GetUInt32();
    private async Task<HttpResponseMessage> DecideCorrection(HttpClient c,Guid id,uint version,bool approve=true)=>await Write(c,$"/api/v1/attendance/corrections/{id}/{(approve?"approve":"reject")}",new AttendanceCorrectionDecision(version,null));
    [Fact]
    public async Task Past_attendance_demo_seed_preserves_pending_or_reviewed_requests_without_automatic_changes()
    {
        SetVisitClock();await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var collections=scope.ServiceProvider.GetRequiredService<CollectionService>();await GroupPlacementDemoSeed.Seed(db,collections);await AttendanceStatesDemoSeed.Seed(db,collections);var before=(await db.Collections.CountAsync(),await db.PlayerAttendances.CountAsync(),await db.StaffAttendances.CountAsync());await PastAttendanceDemoSeed.Seed(db,factory.VisitClock);var id=PastAttendanceDemoSeed.RequestId(PlacementToday);Assert.True(await db.AttendanceCorrections.AnyAsync(c=>c.Id==id));var count=await db.AttendanceCorrections.CountAsync();await PastAttendanceDemoSeed.Seed(db,factory.VisitClock);Assert.Equal(count,await db.AttendanceCorrections.CountAsync());Assert.Equal(before,(await db.Collections.CountAsync(),await db.PlayerAttendances.CountAsync(),await db.StaffAttendances.CountAsync()));
    }
    [Fact]
    public async Task Past_attendance_is_readable_but_only_an_approved_snapshot_can_change_balance_once()
    {
        SetVisitClock();using var first=await Staff();var f=await AttendanceReady(first);(await AttendanceWrite(first,f.Next,new PlayerAttendanceChange(f.First,AttendanceStatus.Present,0))).EnsureSuccessStatusCode();var version=await AttendanceVersion(first,f.Next,f.First);factory.VisitClock.Now=factory.VisitClock.GetUtcNow().AddDays(1);using var owner=await Staff();Assert.Equal(HttpStatusCode.Conflict,(await AttendanceWrite(owner,f.Next,new PlayerAttendanceChange(f.First,AttendanceStatus.Absent,version))).StatusCode);var roster=await owner.GetFromJsonAsync<JsonElement>($"/api/v1/attendance/sessions/{f.Next}/players");Assert.False(roster.GetProperty("canManageAttendance").GetBoolean());Assert.True(roster.GetProperty("canRequestCorrection").GetBoolean());
        await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var before=await db.SubscriptionPeriods.Where(p=>p.SportEnrollmentId==f.First).Select(p=>p.RemainingSessions).SingleAsync();var money=await db.Collections.CountAsync();var key=Guid.NewGuid().ToString();var body=CorrectionBody(f.First,version);var id=await RequestCorrection(owner,f.Next,body,key);Assert.Equal(id,await RequestCorrection(owner,f.Next,body,key));Assert.Equal(HttpStatusCode.Conflict,(await CompensationCommand(owner,CorrectionPath(f.Next),body with{Reason="تغيير بعد الإرسال"},key)).StatusCode);Assert.Equal(before,await db.SubscriptionPeriods.Where(p=>p.SportEnrollmentId==f.First).Select(p=>p.RemainingSessions).SingleAsync());var revision=await CorrectionVersion(owner,id);(await DecideCorrection(owner,id,revision)).EnsureSuccessStatusCode();(await DecideCorrection(owner,id,revision)).EnsureSuccessStatusCode();Assert.Equal(before+1,await db.SubscriptionPeriods.Where(p=>p.SportEnrollmentId==f.First).Select(p=>p.RemainingSessions).SingleAsync());Assert.Equal(money,await db.Collections.CountAsync());Assert.Equal(2,await db.SubscriptionSessionMovements.CountAsync(m=>m.PlayerAttendance.SportEnrollmentId==f.First));var saved=await db.AttendanceCorrections.SingleAsync(c=>c.Id==id);Assert.Equal(AttendanceCorrectionState.Approved,saved.State);Assert.NotNull(saved.AppliedAtUtc);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"AttendanceCorrections\" WHERE \"Id\"={id}"))).SqlState);saved.Reason="changed";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());
    }
    [Fact]
    public async Task Past_attendance_staff_correction_has_no_automatic_pay_or_player_attendance_effect_and_rejection_has_none()
    {
        SetVisitClock();using var first=await Staff();var f=await AttendanceReady(first);(await Write(first,$"/api/v1/attendance/sessions/{f.Next}/staff",new{items=new[]{new StaffAttendanceChange(f.Coach,AttendanceStatus.Present,0)}},true)).EnsureSuccessStatusCode();var staff=await first.GetFromJsonAsync<JsonElement>($"/api/v1/attendance/sessions/{f.Next}/staff");var version=staff.EnumerateArray().Single(m=>m.GetProperty("academyMembershipId").GetGuid()==f.Coach).GetProperty("version").GetUInt32();factory.VisitClock.Now=factory.VisitClock.GetUtcNow().AddDays(1);using var owner=await Staff();await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var before=(await db.PlayerAttendances.CountAsync(),await db.Collections.CountAsync(),await db.PayrollSettlements.CountAsync());var id=await RequestCorrection(owner,f.Next,CorrectionBody(f.Coach,version,kind:AttendanceCorrectionKind.Staff));(await DecideCorrection(owner,id,await CorrectionVersion(owner,id))).EnsureSuccessStatusCode();Assert.Equal(AttendanceStatus.Absent,await db.StaffAttendances.Where(a=>a.TrainingSessionId==f.Next&&a.AcademyMembershipId==f.Coach).Select(a=>a.Status).SingleAsync());Assert.Equal(before,(await db.PlayerAttendances.CountAsync(),await db.Collections.CountAsync(),await db.PayrollSettlements.CountAsync()));var rejected=await RequestCorrection(owner,f.Next,CorrectionBody(f.Second));(await DecideCorrection(owner,rejected,await CorrectionVersion(owner,rejected),false)).EnsureSuccessStatusCode();Assert.False(await db.PlayerAttendances.AnyAsync(a=>a.TrainingSessionId==f.Next&&a.SportEnrollmentId==f.Second));Assert.Equal(HttpStatusCode.Conflict,(await DecideCorrection(owner,rejected,await CorrectionVersion(owner,rejected))).StatusCode);
    }
    [Fact]
    public async Task Past_attendance_competing_approvals_have_one_winner_and_do_not_overwrite_a_newer_version()
    {
        SetVisitClock();using var first=await Staff();var f=await AttendanceReady(first);factory.VisitClock.Now=factory.VisitClock.GetUtcNow().AddDays(1);using var owner=await Staff();var a=await RequestCorrection(owner,f.Next,CorrectionBody(f.First,after:AttendanceStatus.Present));var b=await RequestCorrection(owner,f.Next,CorrectionBody(f.First,after:AttendanceStatus.Excused));var results=await Task.WhenAll(DecideCorrection(owner,a,await CorrectionVersion(owner,a)),DecideCorrection(owner,b,await CorrectionVersion(owner,b)));Assert.Single(results,r=>r.IsSuccessStatusCode);Assert.Single(results,r=>r.StatusCode==HttpStatusCode.Conflict);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();Assert.Equal(1,await db.AttendanceCorrections.CountAsync(c=>(c.Id==a||c.Id==b)&&c.State==AttendanceCorrectionState.Approved));Assert.Equal(1,await db.AttendanceCorrections.CountAsync(c=>(c.Id==a||c.Id==b)&&c.State==AttendanceCorrectionState.Pending));Assert.Single(await db.PlayerAttendances.Where(p=>p.TrainingSessionId==f.Next&&p.SportEnrollmentId==f.First).ToArrayAsync());
    }
    [Fact]
    public async Task Past_attendance_rejects_future_missing_version_missing_reason_cancelled_and_expired_requests()
    {
        SetVisitClock();using var first=await Staff();var f=await AttendanceReady(first);var body=CorrectionBody(f.First);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await CompensationCommand(first,CorrectionPath(f.Next),body)).StatusCode);factory.VisitClock.Now=factory.VisitClock.GetUtcNow().AddDays(1);using var owner=await Staff();Assert.Equal(HttpStatusCode.UnprocessableEntity,(await CompensationCommand(owner,CorrectionPath(f.Next),body with{Reason=""})).StatusCode);Assert.Equal(HttpStatusCode.UnprocessableEntity,(await CompensationCommand(owner,CorrectionPath(f.Next),body with{Items=[new(f.First,AttendanceStatus.Absent,null)]})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await owner.PostAsJsonAsync(CorrectionPath(f.Next),body)).StatusCode);var id=await RequestCorrection(owner,f.Next,body);var version=await CorrectionVersion(owner,id);factory.VisitClock.Now=factory.VisitClock.GetUtcNow().AddDays(8);using var refreshed=await Staff();Assert.Equal(HttpStatusCode.Conflict,(await DecideCorrection(refreshed,id,version)).StatusCode);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();Assert.False(await db.PlayerAttendances.AnyAsync(a=>a.TrainingSessionId==f.Next));(await db.TrainingSessions.SingleAsync(s=>s.Id==f.Next)).Status=TrainingSessionStatus.Cancelled;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.UnprocessableEntity,(await CompensationCommand(refreshed,CorrectionPath(f.Next),body)).StatusCode);
    }
    [Fact]
    public async Task Past_attendance_admin_requires_current_branch_and_edit_grant_but_cannot_approve_even_with_all_CRUD()
    {
        SetVisitClock();using var first=await Staff();var f=await AttendanceReady(first);var email="past.admin."+Guid.NewGuid().ToString("N")+"@example.test";var created=await Write(first,"/api/v1/manage/staff",new StaffWrite("إداري تصحيح اصطناعي",email,"010"+Random.Shared.Next(10000000,99999999),"Demo-Only-123!",AcademyRole.AcademyAdmin,null));created.EnsureSuccessStatusCode();var member=(await created.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();factory.VisitClock.Now=factory.VisitClock.GetUtcNow().AddDays(1);using var owner=await Staff();using var admin=await Staff(email);StaffAccessWrite Access(Guid branch,bool edit)=>new(false,[branch],StaffAccessRules.Modules.Select(m=>new StaffActionValue(m,true,true,edit,true)).ToArray());(await Write(owner,$"/api/v1/manage/staff/{member}/access",Access(f.Branch,false),true)).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Forbidden,(await CompensationCommand(admin,CorrectionPath(f.Next),CorrectionBody(f.First))).StatusCode);(await Write(owner,$"/api/v1/manage/staff/{member}/access",Access(f.OtherBranch,true),true)).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.NotFound,(await CompensationCommand(admin,CorrectionPath(f.Next),CorrectionBody(f.First))).StatusCode);(await Write(owner,$"/api/v1/manage/staff/{member}/access",Access(f.Branch,true),true)).EnsureSuccessStatusCode();var id=await RequestCorrection(admin,f.Next,CorrectionBody(f.First));Assert.Equal(HttpStatusCode.Forbidden,(await DecideCorrection(admin,id,await CorrectionVersion(admin,id))).StatusCode);using var foreign=await Staff("owner.future@example.test");Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync($"/api/v1/attendance/corrections/{id}")).StatusCode);using var coach=await OverrideCoach(f.Coach);using var guardian=await Guardian();Assert.Equal(HttpStatusCode.Forbidden,(await CompensationCommand(coach,CorrectionPath(f.Next),CorrectionBody(f.First))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await guardian.GetAsync("/api/v1/attendance/corrections")).StatusCode);(await DecideCorrection(owner,id,await CorrectionVersion(owner,id))).EnsureSuccessStatusCode();
    }
}
